var IDI_PEDACOS=null,IDI_CACHE=new Map();
/* pedaços com 7 letras ou mais (ou com pontuação que os marca), os mais compridos primeiro */
function idiPedacos(){
  if(IDI_PEDACOS)return IDI_PEDACOS;var L=[];
  IDI_FRAG.split('\n').forEach(function(l){var p=l.split('¦');if(p.length===3){var a=p[0].trim();if(a.length>=7||/[:,?]$/.test(a)||/^[·,]/.test(a))L.push([a,p[1].trim(),p[2].trim()])}});
  return IDI_PEDACOS=L.sort(function(a,b){return b[0].length-a[0].length});
}
/* troca, dentro de um texto que não está na tabela, os pedaços conhecidos; null se nada mudou */
function idiPorPedacos(t){
  var k=idiAtual()==='en'?1:2,ch=k+'|'+t;if(IDI_CACHE.has(ch))return IDI_CACHE.get(ch);
  /* "Estudo na UFRJ · Moro na Vila Residencial": cada parte separada por · é traduzida sozinha */
  if(t.indexOf(' · ')>0){var ps=t.split(' · '),algum=false,rs=ps.map(function(x){var y=idiTraduz(x);if(y!=null)algum=true;return y==null?x:y});
    if(algum){IDI_CACHE.set(ch,rs.join(' · '));return rs.join(' · ')}}
  var L=idiPedacos(),r=t,mudou=false;
  for(var i=0;i<L.length;i++){if(r.indexOf(L[i][0])>=0){r=r.split(L[i][0]).join(L[i][k]);mudou=true}}
  if(mudou){r=r.replace(/\bhá (\d+ (?:s|min|h))/g,k===1?'$1 ago':'hace $1')}
  if(IDI_CACHE.size>4000)IDI_CACHE.clear();
  IDI_CACHE.set(ch,mudou?r:null);return mudou?r:null;
}
IDI_PAD.push([/^(.+?) perto de (.+)$/,function(_,a,b){var r=idiMapa().get(a);return (r?r[0]:a)+' near '+b},function(_,a,b){var r=idiMapa().get(a);return (r?r[1]:a)+' cerca de '+b}]);
IDI_PAD.push([/^Parada (.+), linhas (.+)$/,'Stop $1, lines $2','Parada $1, líneas $2']);
IDI_PAD.push([/^Guarita (\d+), segurança$/,'Guard post $1, security','Garita $1, seguridad']);
